function memoComponent(Component, arePropsEqual = shallowEqual) {
  let prevProps = null;
  let prevResult = null;

  return function Memoized(props) {
    if (prevProps !== null && arePropsEqual(prevProps, props)) {
      return prevResult;
    }
    prevResult = Component(props);
    prevProps = props;
    return prevResult;
  };
}
